import 'package:flutter/foundation.dart';

// Settings → Employee ID Format — web app/dashboard/settings/employee-code/
// page.tsx against production GET/PUT /settings/employee-code/
// (accounts EmployeeCodeSettingsView: IsAuthenticated + CanManageRoles =
// settings.edit; EmployeeCodeSettingsSerializer).
//
// New employee codes are generated by the backend
// (EmployeeCodeSettings.build_base_id / generate_employee_id) from the prefix,
// the date of joining (DDMM) and the name initials (first letter of the
// name's first word + of its last word), in the company's `id_format`
// (accounts migration 0103):
//   date_initials   → prefix + DDMM + both initials        e.g. RSS0308TG
//   first_date_last → prefix + first initial + DDMM + last  e.g. RIST0308G
// with 2, 3, … appended when that code is already taken. The format applies
// to employees created afterwards; existing codes are never changed. `padding`
// and `next_sequence` are still in the API contract but no longer affect
// generated codes; web never lets them be edited and sends back whatever GET
// returned. `format_description` (also returned) is not shown — web builds
// its own description per format.

/// Web FORMAT_OPTIONS (value, label, description), in web's order.
const kEmployeeIdFormats = <(String, String, String)>[
  (
    'date_initials',
    'Prefix + DDMM + initials',
    'prefix + date of joining (DDMM) + first and last name initials',
  ),
  (
    'first_date_last',
    'Prefix + first initial + DDMM + last initial',
    'prefix + first name initial + date of joining (DDMM) + last name initial',
  ),
];

/// Web toSettings default (and the model default) when the server sends no
/// id_format (an older backend).
const kDefaultEmployeeIdFormat = 'date_initials';

/// Web: `FORMAT_OPTIONS.find(o => o.value === id_format) ?? FORMAT_OPTIONS[0]`.
String employeeIdFormatDescription(String format) =>
    (kEmployeeIdFormats.where((f) => f.$1 == format).firstOrNull ?? kEmployeeIdFormats.first).$3;

@immutable
class EmployeeCodeSettings {
  const EmployeeCodeSettings({
    required this.prefix,
    this.idFormat = kDefaultEmployeeIdFormat,
    this.padding,
    this.nextSequence,
  });

  /// As stored ('' when absent). Shown as-is, even a legacy value the
  /// current rule would refuse — the user then has to correct it to save.
  final String prefix;

  /// The stored format; [kDefaultEmployeeIdFormat] when the server didn't
  /// send one. A value this app doesn't know is kept as-is (and sent back
  /// unchanged), never replaced.
  final String idFormat;

  /// Carried through untouched. Null when the server didn't send one: then
  /// it is left out of the save (the stored value stays), never replaced by a
  /// made-up default.
  final int? padding;
  final int? nextSequence;

  factory EmployeeCodeSettings.fromJson(Map<String, dynamic> json) => EmployeeCodeSettings(
        prefix: json['prefix'] is String ? json['prefix'] as String : '',
        idFormat: json['id_format'] is String && (json['id_format'] as String).isNotEmpty
            ? json['id_format'] as String
            : kDefaultEmployeeIdFormat,
        padding: json['padding'] is int ? json['padding'] as int : null,
        nextSequence: json['next_sequence'] is int ? json['next_sequence'] as int : null,
      );

  /// Web onSave: `{prefix: trim().toUpperCase(), id_format, padding,
  /// next_sequence}`.
  Map<String, dynamic> toPayload(String prefixInput, String idFormat) => {
        'prefix': prefixInput.trim().toUpperCase(),
        'id_format': idFormat,
        if (padding != null) 'padding': padding,
        if (nextSequence != null) 'next_sequence': nextSequence,
      };
}

/// Web validate(): on the trimmed value, ASCII letters only.
String? validateEmployeeCodePrefix(String input) {
  final p = input.trim();
  if (p.isEmpty) return 'Prefix is required.';
  if (!RegExp(r'^[A-Za-z]+$').hasMatch(p)) return 'Prefix must contain letters only.';
  return null;
}

/// Web maxLength on the Prefix input (= the model's max_length).
const kEmployeeCodePrefixMaxLength = 10;

class EmployeeCodePreviewRow {
  const EmployeeCodePreviewRow(this.code, this.label, [this.note]);
  final String code;
  final String label;
  final String? note;
}

/// Web buildPreview: three fixed example people (name, DDMM, initials), with
/// the typed prefix (trimmed, uppercased; "EMP" while empty), laid out per
/// [format] — first_date_last puts the date between the two initials; any
/// other value uses date_initials (as web's ternary).
List<EmployeeCodePreviewRow> employeeCodePreview(String prefixInput, [String format = kDefaultEmployeeIdFormat]) {
  final typed = prefixInput.trim().toUpperCase();
  final p = typed.isEmpty ? 'EMP' : typed;
  String code(String ddmm, String initials) =>
      format == 'first_date_last' ? '$p${initials[0]}$ddmm${initials[1]}' : '$p$ddmm$initials';
  return [
    EmployeeCodePreviewRow(code('0308', 'TG'), 'Teerdaveni Gedela (joined 03 Aug)'),
    EmployeeCodePreviewRow(code('1509', 'RK'), 'Ravi Kumar (joined 15 Sep)'),
    EmployeeCodePreviewRow('${code('1509', 'RK')}2', 'Rahul Kumar (joined 15 Sep)',
        'Same day + same initials as above — a 2 is appended to keep it unique'),
  ];
}

/// A refused save: the server's per-field messages (prefix shown under the
/// field; padding / next_sequence — not editable here — in the banner), or a
/// general message.
class EmployeeCodeSaveError {
  const EmployeeCodeSaveError({this.message, this.fieldErrors = const {}});
  final String? message;
  final Map<String, String> fieldErrors;
}
